INSERT INTO config_settings (setting_key,category,label,data_type,value_json,enabled,description) VALUES
('capacity.manualWorkSegmented','CAPACITY_MODEL','Manual Work Segmented Scheduler','boolean','true'::jsonb,true,'Enable detailed Masking / Fluid Masking / Unmasking workstation + labor-pool finite scheduling.'),
('capacity.manualWorkMainOperations','CAPACITY_MODEL','Manual Work Main Operations','json','["MASKING","FMSKG_CM","UNMASKING"]'::jsonb,true,'Main Operations handled by the v020 manual-work scheduler.'),
('capacity.maskingResourceCode','CAPACITY_MODEL','Masking Workstation Resource','string','"MASKING"'::jsonb,true,'Physical workstation resource for Masking and Fluid Masking.'),
('capacity.unmaskingResourceCode','CAPACITY_MODEL','Unmasking Workstation Resource','string','"UNMASKING"'::jsonb,true,'Physical workstation resource for Unmasking.'),
('capacity.maskingLaborResourceCode','CAPACITY_MODEL','Masking Labor Pool','string','"MASKING_LABOR"'::jsonb,true,'Shared operator pool consumed by masking setup/work/release segments.'),
('capacity.unmaskingLaborResourceCode','CAPACITY_MODEL','Unmasking Labor Pool','string','"UNMASKING_LABOR"'::jsonb,true,'Shared operator pool consumed by unmasking setup/work/release segments.'),
('capacity.manualSetupAggregation','CAPACITY_MODEL','Manual Setup Aggregation','string','"MAX_MEMBER"'::jsonb,true,'For a grouped manual batch, use the maximum member setup once. Alternatives supported by engine: SUM_MEMBER or FIXED.'),
('capacity.maskingDefaultSetupMinutes','CAPACITY_MODEL','Masking Default Setup Minutes','number','10'::jsonb,true,'Fallback setup when the selected Process Time rule does not expose setupMinutes.'),
('capacity.unmaskingDefaultSetupMinutes','CAPACITY_MODEL','Unmasking Default Setup Minutes','number','5'::jsonb,true,'Fallback setup for Unmasking.'),
('capacity.manualReleaseMinutes','CAPACITY_MODEL','Manual Release Minutes','number','5'::jsonb,true,'Default closeout/release segment after manual work.'),
('capacity.manualMaxOperatorsPerBatch','CAPACITY_MODEL','Manual Max Operators per Batch','number','2'::jsonb,true,'Default upper limit for operators assigned simultaneously to one masking/unmasking batch.'),
('capacity.manualOperator2ThresholdWorkMinutes','CAPACITY_MODEL','Manual Additional Operator Threshold','number','240'::jsonb,true,'One-operator labor minutes per effective operator target. Example: >240 labor-minutes allows a second operator when capacity exists.'),
('capacity.manualParallelEfficiency','CAPACITY_MODEL','Manual Parallel Efficiency','number','0.85'::jsonb,true,'Efficiency of each additional operator. Two operators at 0.85 give 1.85 effective operators, avoiding perfect linear scaling.')
