INSERT INTO config_rules (rule_type,code,name,enabled,priority,condition_json,action_json,notes) VALUES
('MANUAL_CAPACITY','MASK_COMPLEX_TWO_OPERATOR','Complex masking operator baseline',true,10,'{"operationCodeIn":["MSKG-DBL","MSKGABP"]}'::jsonb,'{"allowedResources":["MASKING"],"laborResourceCode":"MASKING_LABOR","parallelAllowed":true,"minOperators":1,"maxOperators":2,"operator2ThresholdWorkMinutes":180,"parallelEfficiency":0.80,"releaseMinutes":5}'::jsonb,'Complex masking operations may use two operators earlier; source min/pc remains the work-content basis.'),
